# -- bookkeeping ------------------------------------------------------

def record(self, e, p, status, reason, at, frame):
    self.results[(e, p)] = (status, reason, at, frame)

def terminate(self, state, code, at, source, peer_code):
    self.term = (state, code, at, source, peer_code)
    self.term_at = at
    if self.pending:
        for r in self.pending:
            self.record(r[0], r[1], S_DROP, 'CONNECTION_CLOSED', at, None)
        self.pending = []

def fail(self, e, p, t, code, frame):
    self.terminate('closed', code, t, (e, p, frame), None)
    self.record(e, p, S_ERR, code, t, frame)

def get_stream(self, sid, j):
    s = self.streams.get(sid)
    if s is None:
        s = Stream(sid)
        self.streams[sid] = s
        j.new_stream(sid)
    j.snap_stream(s)
    return s

# -- events -----------------------------------------------------------

def key_event(self, e, ev, t):
    level = ev['level']
    action = ev['action']
    cur = self.keys[level]
    if action == 'discard':
        if cur != 'discarded':
            self.keys[level] = 'discarded'
            if self.pending:
                keep = []
                for r in self.pending:
                    if r[3] == level:
                        self.record(r[0], r[1], S_DROP, 'KEYS_DISCARDED', t, None)
                    else:
                        keep.append(r)
                self.pending = keep
    else:
        if cur == 'absent':
            self.keys[level] = 'live'
            drain = []
            keep = []
            for r in self.pending:
                if r[3] == level:
                    drain.append(r)
                else:
                    keep.append(r)
            self.pending = keep
            for r in drain:
                if self.term is not None:
                    self.record(r[0], r[1], S_DROP, 'CONNECTION_CLOSED', self.term_at, None)
                else:
                    self.process(r[0], r[1], r[4], t)

def datagram(self, e, ev, t):
    pkts = ev['packets']
    size = ev['bytes']
    bad = False
    for pkt in pkts[:-1]:
        if pkt['level'] == 'A':
            bad = True
            break
    if bad:
        for p in range(len(pkts)):
            self.record(e, p, S_DROP, 'LAYOUT', t, None)
        return
    for p in range(len(pkts)):
        pkt = pkts[p]
        if self.term is not None:
            self.record(e, p, S_DROP, 'CONNECTION_CLOSED', t, None)
            continue
        lvl = pkt['level']
        if lvl == 'I' and size < 1200:
            self.record(e, p, S_DROP, 'INITIAL_TOO_SMALL', t, None)
            continue
        if lvl == 'Z' and not self.early:
            self.record(e, p, S_DROP, 'EARLY_REJECTED', t, None)
            continue
        ks = self.keys[lvl]
        if ks == 'discarded':
            self.record(e, p, S_DROP, 'KEYS_DISCARDED', t, None)
            continue
        if ks == 'absent':
            if len(self.pending) < self.buffer_packets:
                self.pending.append((e, p, t, lvl, pkt))
            else:
                self.record(e, p, S_DROP, 'BUFFER_FULL', t, None)
            continue
        self.process(e, p, pkt, t)

# -- packet -----------------------------------------------------------

def process(self, e, p, pkt, t):
    lvl = pkt['level']
    pn = pkt['pn']
    if not pkt['auth']:
        self.record(e, p, S_DROP, 'AUTH', t, None)
        return
    key = 'A' if (lvl == 'Z' or lvl == 'A') else lvl
    if pn in self.pnsets[key]:
        self.record(e, p, S_DUP, 'DUPLICATE', t, None)
        return
    frames = pkt['frames']
    if not frames:
        self.fail(e, p, t, 'FRAME_ENCODING_ERROR', None)
        return
    for i in range(len(frames)):
        f = frames[i]
        if f['type'] == 'UNKNOWN':
            self.fail(e, p, t, 'FRAME_ENCODING_ERROR', i)
            return
        if not permitted(lvl, f):
            self.fail(e, p, t, 'PROTOCOL_VIOLATION', i)
            return
    j = Journal(self)
    i = None
    try:
        for i in range(len(frames)):
            f = frames[i]
            ft = f['type']
            if ft == 'PADDING' or ft == 'PING':
                continue
            if ft == 'ACK':
                self.do_ack(lvl, f)
            elif ft == 'CRYPTO':
                self.do_crypto(lvl, f, j)
            elif ft == 'STREAM':
                self.do_stream(f, j)
            elif ft == 'RESET_STREAM':
                self.do_reset(f, j)
            elif ft == 'STOP_SENDING':
                self.do_stop(f, j)
            else:  # CLOSE
                app = f['app']
                code = 'PEER_APPLICATION_CLOSE' if app else 'PEER_TRANSPORT_CLOSE'
                self.pnsets[key].add(pn)
                self.last_activity = t
                self.terminate('closed', code, t, (e, p, i), f['code'])
                self.record(e, p, S_OK, 'OK', t, None)
                return
    except Err as ex:
        if ex.frame is None:
            ex.frame = i
        j.rollback()
        self.fail(e, p, t, ex.code, ex.frame)
        return
    self.pnsets[key].add(pn)
    self.last_activity = t
    self.record(e, p, S_OK, 'OK', t, None)

# -- frames -----------------------------------------------------------

def do_ack(self, lvl, f):
    rs = f['ranges']
    if not rs:
        raise Err('FRAME_ENCODING_ERROR')
    prev = None
    for r in rs:
        lo = r[0]
        hi = r[1]
        if lo > hi:
            raise Err('FRAME_ENCODING_ERROR')
        if prev is not None and lo <= prev + 1:
            raise Err('FRAME_ENCODING_ERROR')
        prev = hi
    sent = self.sent[lvl]
    lows = self.sent_lows[lvl]
    for r in rs:
        if not covered(lows, sent, r[0], r[1]):
            raise Err('PROTOCOL_VIOLATION')

